const tenanciesForRenewalReminder = `-- name: TenanciesForRenewalReminder :many
UPDATE tenancies SET renewal_reminder_sent_at = $1::timestamptz
 WHERE id IN (SELECT t.id FROM tenancies t WHERE t.status = 'ACTIVE' AND t.end_date IS NOT NULL AND t.end_date <= $2::date
                AND t.renewal_reminder_sent_at IS NULL ORDER BY t.end_date LIMIT $3 FOR UPDATE SKIP LOCKED)
RETURNING id, property_id, unit_id, listing_id, agreement_id, customer_ref_id, tenant_display_name, status, start_date, end_date, rent_minor, currency, frequency, recurring_fees_minor, escalation_after_months, escalation_bps, due_day, rent_collection, deposit_handling, late_fee_grace_days, late_fee_minor, dispute_flag, schedule_anchor, schedule_materialized_to, move_in_at, termination_effective_date, ended_at, end_reason, renewal_reminder_sent_at, version, created_at, updated_at, rent_free_months
`

type TenanciesForRenewalReminderParams struct {
	Now       time.Time
	WindowEnd time.Time
	MaxRows   int32
}

func (q *Queries) TenanciesForRenewalReminder(ctx context.Context, db DBTX, arg TenanciesForRenewalReminderParams) ([]Tenancy, error) {
	rows, err := db.Query(ctx, tenanciesForRenewalReminder, arg.Now, arg.WindowEnd, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Tenancy
	for rows.Next() {
		var i Tenancy
		if err := rows.Scan(
			&i.ID,
			&i.PropertyID,
			&i.UnitID,
			&i.ListingID,
			&i.AgreementID,
			&i.CustomerRefID,
			&i.TenantDisplayName,
			&i.Status,
			&i.StartDate,
			&i.EndDate,
			&i.RentMinor,
			&i.Currency,
			&i.Frequency,
			&i.RecurringFeesMinor,
			&i.EscalationAfterMonths,
			&i.EscalationBps,
			&i.DueDay,
			&i.RentCollection,
			&i.DepositHandling,
			&i.LateFeeGraceDays,
			&i.LateFeeMinor,
			&i.DisputeFlag,
			&i.ScheduleAnchor,
			&i.ScheduleMaterializedTo,
			&i.MoveInAt,
			&i.TerminationEffectiveDate,
			&i.EndedAt,
			&i.EndReason,
			&i.RenewalReminderSentAt,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RentFreeMonths,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

