func (q *Queries) UpdateUtilityBillState(ctx context.Context, db DBTX, arg UpdateUtilityBillStateParams) (UtilityBill, error) {
	row := db.QueryRow(ctx, updateUtilityBillState,
		arg.ID,
		arg.Version,
		arg.Status,
		arg.Allocation,
		arg.AllocationRuleVersion,
		arg.OriginalAllocation,
		arg.DisputeReason,
		arg.UpdatedAt,
	)
	var i UtilityBill
	err := row.Scan(
		&i.ID,
		&i.UtilityAccountID,
		&i.PropertyID,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.AmountMinor,
		&i.Currency,
		&i.BillMediaID,
		&i.Status,
		&i.Allocation,
		&i.AllocationRuleVersion,
		&i.OriginalAllocation,
		&i.DisputeReason,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const voidSignatureRequests = `-- name: VoidSignatureRequests :exec
UPDATE signature_requests SET status = 'VOIDED', version = version + 1, updated_at = $3
 WHERE agreement_id = $1 AND agreement_version_no = $2 AND status NOT IN ('SIGNED','VOIDED')
`

type VoidSignatureRequestsParams struct {
	AgreementID        ids.ID
	AgreementVersionNo int32
	UpdatedAt          time.Time
}

func (q *Queries) VoidSignatureRequests(ctx context.Context, db DBTX, arg VoidSignatureRequestsParams) error {
	_, err := db.Exec(ctx, voidSignatureRequests, arg.AgreementID, arg.AgreementVersionNo, arg.UpdatedAt)
	return err
}
